"use client";
import { useState } from "react";

const input = "mt-2 min-h-12 w-full rounded-xl border border-slate-300 bg-white px-3.5 text-sm outline-none focus:border-orange-600 focus:ring-2 focus:ring-orange-100";
export default function VendorPricingConfig({ config, busy, onSave, onError }) {
  const [tax, setTax] = useState(() => config?.taxProfile || { legalName: "", gstin: "", state: "", stateCode: "", isGstRegistered: false });
  const [shipping, setShipping] = useState(() => config?.shippingPolicy ? { mode: config.shippingPolicy.mode, flatCharge: config.shippingPolicy.flatChargePaise == null ? "" : String(config.shippingPolicy.flatChargePaise / 100), freeAbove: config.shippingPolicy.freeAbovePaise == null ? "" : String(config.shippingPolicy.freeAbovePaise / 100) } : { mode: "MANUAL_FREIGHT_QUOTE", flatCharge: "", freeAbove: "" });
  const submit = (event) => {
    event.preventDefault();
    const flatChargePaise = shipping.flatCharge === "" ? null : Math.round(Number(shipping.flatCharge) * 100);
    const freeAbovePaise = shipping.freeAbove === "" ? null : Math.round(Number(shipping.freeAbove) * 100);
    if (!tax.legalName.trim() || !tax.state.trim() || !/^\d{2}$/.test(tax.stateCode)) return onError("Enter legal name, state, and an exact two-digit state code.");
    if (tax.isGstRegistered && !tax.gstin.trim()) return onError("GSTIN is required for a GST-registered seller.");
    if ([flatChargePaise, freeAbovePaise].some((value) => value !== null && (!Number.isSafeInteger(value) || value < 0))) return onError("Shipping amounts must be valid non-negative rupee values.");
    const shippingPolicy = { mode: shipping.mode };
    if (["FLAT", "FREE_ABOVE_THRESHOLD"].includes(shipping.mode)) shippingPolicy.flatChargePaise = flatChargePaise;
    if (shipping.mode === "FREE_ABOVE_THRESHOLD") shippingPolicy.freeAbovePaise = freeAbovePaise;
    onSave({ taxProfile: { ...tax, legalName: tax.legalName.trim(), gstin: tax.isGstRegistered ? tax.gstin.trim() : "", state: tax.state.trim(), stateCode: tax.stateCode.trim() }, shippingPolicy });
  };
  const showFlat = ["FLAT", "FREE_ABOVE_THRESHOLD"].includes(shipping.mode);
  return <section><p className="marketplace-eyebrow">Authoritative pricing</p><h2 className="mt-2 text-3xl font-bold">Tax &amp; Shipping</h2><p className="mt-3 text-sm text-slate-600">Configure verified business tax details and one server-owned shipping policy. These values are snapshotted into checkout drafts.</p><form onSubmit={submit} className="mt-7 space-y-7 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:p-7"><fieldset><legend className="text-lg font-bold">Seller tax profile</legend><div className="mt-4 grid gap-4 sm:grid-cols-2"><label className="text-sm font-semibold">Legal business name<input required maxLength={200} className={input} value={tax.legalName} onChange={(event) => setTax({ ...tax, legalName: event.target.value })}/></label><label className="text-sm font-semibold">Registered state<input required maxLength={100} className={input} value={tax.state} onChange={(event) => setTax({ ...tax, state: event.target.value })}/></label><label className="text-sm font-semibold">State code<input required inputMode="numeric" maxLength={2} className={input} value={tax.stateCode} onChange={(event) => setTax({ ...tax, stateCode: event.target.value })} placeholder="07"/></label><label className="flex items-center gap-3 self-end pb-3 text-sm font-semibold"><input type="checkbox" checked={tax.isGstRegistered} onChange={(event) => setTax({ ...tax, isGstRegistered: event.target.checked })}/>GST registered</label>{tax.isGstRegistered && <label className="text-sm font-semibold sm:col-span-2">GSTIN<input required maxLength={15} className={input} value={tax.gstin || ""} onChange={(event) => setTax({ ...tax, gstin: event.target.value.toUpperCase() })}/></label>}</div></fieldset><fieldset className="border-t border-slate-200 pt-6"><legend className="text-lg font-bold">Shipping policy</legend><div className="mt-4 grid gap-4 sm:grid-cols-2"><label className="text-sm font-semibold sm:col-span-2">Mode<select className={input} value={shipping.mode} onChange={(event) => setShipping({ ...shipping, mode: event.target.value })}><option value="FREE">Free shipping</option><option value="FLAT">Flat charge</option><option value="FREE_ABOVE_THRESHOLD">Free above threshold</option><option value="MANUAL_FREIGHT_QUOTE">Manual freight quote</option></select></label>{showFlat && <label className="text-sm font-semibold">Flat charge (INR)<input required type="number" min="0" step="0.01" className={input} value={shipping.flatCharge} onChange={(event) => setShipping({ ...shipping, flatCharge: event.target.value })}/></label>}{shipping.mode === "FREE_ABOVE_THRESHOLD" && <label className="text-sm font-semibold">Free above (INR)<input required type="number" min="0.01" step="0.01" className={input} value={shipping.freeAbove} onChange={(event) => setShipping({ ...shipping, freeAbove: event.target.value })}/></label>}</div></fieldset><button disabled={busy} className="marketplace-button-primary disabled:opacity-60">{busy ? "Saving..." : "Save pricing configuration"}</button></form></section>;
}
